const P48=[{label:"Ví dụ: tạo luồng và join",input:"",code:"#include <iostream>\n#include <thread>\nusing namespace std;\n\nvoid chao(int id) {\n    cout << \"Xin chao tu luong \" << id << \"\\n\";\n}\nint main() {\n    thread t1(chao, 1);\n    t1.join();\n    thread t2([]() {\n        cout << \"Xin chao tu lambda\\n\";\n    });\n    t2.join();\n    cout << \"main xong\\n\";\n    return 0;\n}",viz:[{type:"threads"}]},{label:"Ví dụ: hai luồng chạy xen kẽ",input:"",code:"#include <iostream>\n#include <thread>\nusing namespace std;\n\nvoid dem(char ten, int n) {\n    for (int i = 1; i <= n; i++) {\n        cout << ten << i << \" \";\n    }\n}\nint main() {\n    thread a(dem, 'A', 4);\n    thread b(dem, 'B', 4);\n    a.join();\n    b.join();\n    cout << \"\\nxong\\n\";\n    return 0;\n}",viz:[{type:"threads"}]},{label:"Ví dụ: chia việc, truyền tham chiếu bằng ref",input:"",code:"#include <iostream>\n#include <thread>\n#include <vector>\nusing namespace std;\n\nvoid tinhTong(const vector<int>& v, int dau, int cuoi, long long& kq) {\n    kq = 0;\n    for (int i = dau; i < cuoi; i++) {\n        kq += v[i];\n    }\n}\nint main() {\n    vector<int> v;\n    for (int i = 1; i <= 10; i++) v.push_back(i);\n    long long a = 0, b = 0;\n    thread t1(tinhTong, cref(v), 0, 5, ref(a));\n    thread t2(tinhTong, cref(v), 5, 10, ref(b));\n    t1.join();\n    t2.join();\n    cout << a << \" + \" << b << \" = \" << a + b << \"\\n\";\n    return 0;\n}",viz:[{type:"threads"},{type:"mem"}]},{label:"Ví dụ: vector<thread> và lambda",input:"",code:"#include <iostream>\n#include <thread>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int k = 4;\n    vector<long long> kq(k, 0);\n    vector<thread> ds;\n    for (int i = 0; i < k; i++) {\n        ds.emplace_back([i, &kq]() {\n            for (int x = i * 5 + 1; x <= i * 5 + 5; x++) {\n                kq[i] += x;\n            }\n        });\n    }\n    for (auto& t : ds) {\n        t.join();\n    }\n    long long tong = 0;\n    for (int i = 0; i < k; i++) {\n        cout << \"Luong \" << i << \": \" << kq[i] << \"\\n\";\n        tong += kq[i];\n    }\n    cout << \"Tong 1..20 = \" << tong << \"\\n\";\n    return 0;\n}",viz:[{type:"threads"}]},{label:"Lỗi: quên join",input:"",code:"#include <iostream>\n#include <thread>\nusing namespace std;\n\nvoid viec() {\n    cout << \"Dang lam viec\\n\";\n}\nint main() {\n    thread t(viec);\n    cout << \"main ket thuc\\n\";\n    return 0;\n}",viz:[{type:"threads"}]},{label:"Lỗi: tham số tham chiếu không dùng ref",input:"",code:"#include <iostream>\n#include <thread>\nusing namespace std;\n\nvoid tang(int& x) {\n    x++;\n}\nint main() {\n    int a = 0;\n    thread t(tang, a);\n    t.join();\n    cout << a << \"\\n\";\n    return 0;\n}"}];
