makeEx2(document.getElementById("ex-l48"),sim48,[{t:"Tổng bình phương bằng hai luồng",d:"Nhập n (1 ≤ n ≤ 200). Dùng hai luồng: luồng 1 tính tổng k² với k = 1…n/2, luồng 2 tính với k = n/2 + 1…n, mỗi luồng ghi vào biến kết quả riêng (truyền bằng <code>ref<\/code> hoặc lambda bắt tham chiếu). Sau khi join, in hai tổng và tổng chung, mỗi số một dòng.",tests:[{in:"4",out:"5\n25\n30"},{in:"1",out:"0\n1\n1"},{in:"10",out:"55\n330\n385"}],start:"#include <iostream>\n#include <thread>\nusing namespace std;\n\nvoid tongBP(int dau, int cuoi, long long& kq) {\n    // kq = tổng k*k với k từ dau tới cuoi\n}\nint main() {\n    int n;\n    cin >> n;\n    long long a = 0, b = 0;\n    // tạo hai luồng, join\n    cout << a << \"\\n\" << b << \"\\n\" << a + b << \"\\n\";\n    return 0;\n}",need:/thread\s+\w+\s*\([\s\S]*thread\s+\w+\s*\([\s\S]*join[\s\S]*join/,needMsg:"Hãy tạo hai luồng và join cả hai."},{t:"Đếm số nguyên tố theo đoạn",d:"Nhập n (2 ≤ n ≤ 1000) và k (1 ≤ k ≤ 4). Chia đoạn [1, n] thành k phần liên tiếp gần bằng nhau (phần i từ i·n/k + 1 tới (i+1)·n/k). Tạo k luồng, luồng i đếm số nguyên tố trong phần i và ghi vào <code>kq[i]<\/code>. In k dòng <code>Phan i: so_luong<\/code> rồi dòng <code>Tong: t<\/code>.",tests:[{in:"20 2",out:"Phan 0: 4\nPhan 1: 4\nTong: 8"},{in:"10 3",out:"Phan 0: 2\nPhan 1: 1\nPhan 2: 1\nTong: 4"},{in:"2 1",out:"Phan 0: 1\nTong: 1"}],start:"#include <iostream>\n#include <thread>\n#include <vector>\nusing namespace std;\n\nbool laNguyenTo(int x) {\n    if (x < 2) return false;\n    for (int d = 2; d * d <= x; d++)\n        if (x % d == 0) return false;\n    return true;\n}\nint main() {\n    int n, k;\n    cin >> n >> k;\n    vector<int> kq(k, 0);\n    vector<thread> ds;\n    // ds.emplace_back([i, n, k, &kq]() { ... });\n    for (auto& t : ds) t.join();\n    // in kết quả\n    return 0;\n}",need:/thread[\s\S]*join/,needMsg:"Hãy dùng các luồng và join chúng."},{t:"Viết hoa song song",d:"Nhập n (1 ≤ n ≤ 6) rồi n từ (chữ thường). Tạo n luồng, luồng i đổi từ thứ i thành chữ in hoa ngay trong <code>vector&lt;string&gt;<\/code> (mỗi luồng chỉ sửa phần tử của mình). Sau khi join, in các từ cách nhau một dấu cách.",tests:[{in:"3\nmot hai ba",out:"MOT HAI BA"},{in:"1\nx",out:"X"}],start:"#include <iostream>\n#include <thread>\n#include <vector>\n#include <string>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<string> tu(n);\n    for (auto& s : tu) cin >> s;\n    vector<thread> ds;\n    // mỗi luồng: for (char& c : tu[i]) c = c - 'a' + 'A';\n    for (auto& t : ds) t.join();\n    for (int i = 0; i < n; i++) cout << tu[i] << (i + 1 < n ? \" \" : \"\\n\");\n    return 0;\n}",need:/emplace_back|thread\s+\w+\s*\(/,needMsg:"Hãy tạo các luồng."}]);

